use std::time::{Duration, SystemTime};

use bytes::{Bytes, BytesMut};
use futures_util::StreamExt;
use ncore::{Error, HttpRequest, HttpResponse};
use serde::{Deserialize, Serialize};
use serde_json::Value;

pub const ORIGIN: &str = "https://zcode.z.ai";
pub const MESSAGES_URL: &str = "https://zcode.z.ai/api/v1/zcode-plan/anthropic/v1/messages";

pub(crate) fn fail(message: impl Into<String>) -> Error {
    Error::Plugin {
        name: "zcodeacc".into(),
        message: message.into(),
    }
}

/// Native client metadata supplied by the host; device identity is not generated by the plugin.
#[derive(Clone, Serialize, Deserialize)]
pub struct ClientInfo {
    pub version: String,
    pub device_mid: String,
    pub platform: String,
    pub os_category: String,
    pub os_version: String,
    pub language: String,
    pub timezone: String,
}

impl std::fmt::Debug for ClientInfo {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ClientInfo")
            .field("version", &self.version)
            .finish_non_exhaustive()
    }
}

impl ClientInfo {
    pub fn new(version: impl Into<String>, device_mid: impl Into<String>) -> Self {
        let platform = match std::env::consts::OS {
            "windows" => "win32",
            "macos" => "darwin",
            other => other,
        };
        let arch = match std::env::consts::ARCH {
            "x86_64" => "x64",
            "aarch64" => "arm64",
            other => other,
        };
        Self {
            version: version.into(),
            device_mid: device_mid.into(),
            platform: format!("{platform}-{arch}"),
            os_category: match platform {
                "win32" => "windows",
                "darwin" => "macos",
                _ => "linux",
            }
            .into(),
            os_version: "unknown".into(),
            language: "unknown".into(),
            timezone: "unknown".into(),
        }
    }

    pub(crate) fn validate(&self) -> Result<(), Error> {
        for value in [
            &self.version,
            &self.device_mid,
            &self.platform,
            &self.os_category,
            &self.os_version,
            &self.language,
            &self.timezone,
        ] {
            if value.is_empty() || !value.bytes().all(|b| (32..=126).contains(&b)) {
                return Err(fail("invalid ZCode client metadata"));
            }
        }
        Ok(())
    }

    pub(crate) fn headers(&self, model: bool) -> Vec<(String, String)> {
        let mut headers = vec![
            (
                "user-agent".into(),
                format!(
                    "ZCode/{}{}",
                    self.version,
                    if model {
                        " ai-sdk/anthropic/3.0.81"
                    } else {
                        ""
                    }
                ),
            ),
            ("http-referer".into(), ORIGIN.into()),
            (
                "x-title".into(),
                format!("Z Code@{}", if model { "cli" } else { "electron" }),
            ),
            ("x-zcode-app-version".into(), self.version.clone()),
            ("x-release-channel".into(), "production".into()),
            ("x-client-language".into(), self.language.clone()),
            ("x-client-timezone".into(), self.timezone.clone()),
            ("x-platform".into(), self.platform.clone()),
            ("x-os-category".into(), self.os_category.clone()),
            ("x-os-version".into(), self.os_version.clone()),
            (
                "accept".into(),
                if model {
                    "application/json, text/event-stream"
                } else {
                    "application/json"
                }
                .into(),
            ),
        ];
        if model {
            headers.extend([
                ("content-type".into(), "application/json".into()),
                ("anthropic-version".into(), "2023-06-01".into()),
                ("x-zcode-agent".into(), "glm".into()),
                ("x-zcode-session-type".into(), "main".into()),
            ]);
        } else {
            headers.push(("x-device-mid".into(), self.device_mid.clone()));
        }
        headers
    }
}

pub(crate) fn escape(value: &str) -> String {
    value
        .bytes()
        .map(|b| {
            if b.is_ascii_alphanumeric() || b"-._~".contains(&b) {
                (b as char).to_string()
            } else {
                format!("%{b:02X}")
            }
        })
        .collect()
}

pub(crate) fn json_request(
    method: &str,
    path: &str,
    client: &ClientInfo,
    value: Option<Value>,
) -> HttpRequest {
    let mut headers = client.headers(false);
    let body = match value {
        Some(value) => {
            headers.push(("content-type".into(), "application/json".into()));
            Bytes::from(value.to_string())
        }
        None => Bytes::new(),
    };
    HttpRequest {
        method: method.into(),
        url: format!("{ORIGIN}{path}"),
        headers,
        body,
    }
}

pub(crate) struct CallError {
    pub error: Error,
    pub delay: Duration,
}

impl From<Error> for CallError {
    fn from(error: Error) -> Self {
        Self {
            error,
            delay: Duration::from_secs(10),
        }
    }
}

pub(crate) async fn json_response(response: HttpResponse) -> Result<Value, CallError> {
    let status = response.status;
    let retry = response
        .header("retry-after")
        .and_then(|s| s.parse::<u64>().ok())
        .map(Duration::from_secs)
        .or_else(|| {
            response
                .header("retry-after")
                .and_then(|s| httpdate::parse_http_date(s).ok())
                .map(|date| date.duration_since(SystemTime::now()).unwrap_or_default())
        })
        .unwrap_or(Duration::from_secs(10))
        .clamp(Duration::from_secs(1), Duration::from_secs(3600));
    let mut body = response.body;
    let mut bytes = BytesMut::new();
    while let Some(chunk) = body.next().await {
        let chunk = chunk.map_err(Error::from)?;
        if bytes.len().saturating_add(chunk.len()) > 2 * 1024 * 1024 {
            return Err(fail("account response exceeds size limit").into());
        }
        bytes.extend_from_slice(&chunk);
    }
    let value: Value = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
    if !(200..300).contains(&status) || value["code"].as_i64() != Some(0) {
        let code = value["code"].as_i64();
        return Err(CallError {
            error: fail(format!(
                "ZCode account request failed (HTTP {status}, code {code:?})"
            )),
            delay: retry,
        });
    }
    value
        .get("data")
        .cloned()
        .filter(|v| v.is_object())
        .ok_or_else(|| fail("missing ZCode account response data").into())
}
